type ResultMode = 'none'|'number'|'text'|'choice'|'money'
type ResultEntry = {id:string;value:string;note:string;at:string;highlight?:boolean}
type Task = {id:string;title:string;date:string;time:string;category:string;note:string;done:boolean;projectId?:string;parentTaskId?:string;why?:string;priority?:boolean;outcome?:'reached'|'not_reached'|'cancelled';cancelReason?:string;cancelNote?:string;createdAt?:string;lastResultAt?:string;resultMode?:ResultMode;resultQuestion?:string;targetValue?:number;unit?:string;resultValue?:string;resultStatus?:'partial'|'reached'|'exceeded'|'not_reached';resultHistory?:ResultEntry[];incomePromptDismissed?:boolean;incomeOperationCreated?:boolean}
type Thought = {id:string;text:string;createdAt:string;convertedAt?:string;taskId?:string;archived?:boolean}
type HabitSchedule = {type:'daily'|'weekdays'|'weekly'|'custom';days:number[];target:number}
