const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
const addDays=(date:string,n:number)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
const id=()=>crypto.randomUUID?.()??String(Date.now()+Math.random())
function load<T>(key:string,initial:T):T{try{const v=localStorage.getItem('focusflow:'+key);return v?JSON.parse(v) as T:initial}catch{return initial}}
function save<T>(key:string,value:T){try{localStorage.setItem('focusflow:'+key,JSON.stringify(value))}catch{}}
const dateLabel=(v:string)=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long'}).format(new Date(v+'T12:00:00'))
const weekdays=['Пн','Вт','Ср','Чт','Пт','Сб','Вс']
const quote={title:'Не нужно успеть всё.',subtitle:'Достаточно выбрать то, что действительно важно сегодня.'}
