function weekDay(date:string){return (new Date(date+'T12:00:00').getDay()+6)%7}
function scheduleAt(h:Habit,date:string):HabitSchedule{if(h.createdAt&&date<h.createdAt.slice(0,10))return {type:'custom',days:[],target:0};const history=(h.scheduleHistory??[]).filter(x=>x.from<=date).sort((a,b)=>b.from.localeCompare(a.from));return history[0]?.schedule??h.schedule??{type:'daily',days:[0,1,2,3,4,5,6],target:7}}
function isDue(h:Habit,date:string){const s=scheduleAt(h,date);if(s.type==='daily')return true;if(s.type==='weekdays')return weekDay(date)<5;if(s.type==='weekly')return false;return s.days.includes(weekDay(date))}
function habitStreak(h:Habit){let cursor=today(),count=0;if(!h.log.includes(cursor)&&isDue(h,cursor))cursor=addDays(cursor,-1);for(let i=0;i<370;i++){if(isDue(h,cursor)){if(h.log.includes(cursor))count++;else break}cursor=addDays(cursor,-1)}return count}
function habitBestStreak(h:Habit){let best=0,current=0;const start=addDays(today(),-370);for(let i=0;i<=370;i++){const d=addDays(start,i);if(isDue(h,d)){if(h.log.includes(d))current++;else current=0;best=Math.max(best,current)}}return best}
function normalizeHabit(h:Habit):Habit{const createdAt=h.createdAt??h.log?.[0]??today();const normalizeSchedule=(value:HabitSchedule):HabitSchedule=>{const days=[...new Set((value.days??[]).filter(d=>Number.isInteger(d)&&d>=0&&d<=6))].sort((a,b)=>a-b);if(value.type==='weekly')return {type:'custom',days,target:days.length};return {...value,days,target:days.length||value.target||0}};const schedule=normalizeSchedule(h.schedule??{type:'daily',days:[0,1,2,3,4,5,6],target:7});const history=(h.scheduleHistory??[{from:createdAt,schedule}]).map(entry=>({from:entry.from,schedule:normalizeSchedule(entry.schedule)}));const detail=schedule.type==='daily'?'Каждый день':schedule.type==='weekdays'?'По будням':schedule.days.length?schedule.days.map(d=>weekdays[d]).join(', '):'Настройте дни недели';return {...h,createdAt,schedule,detail,scheduleHistory:history.length?history:[{from:createdAt,schedule}]}}
