 useEffect(()=>save('tasks',tasks),[tasks]);useEffect(()=>save('thoughts',thoughts),[thoughts]);useEffect(()=>save('habits',habits),[habits]);useEffect(()=>save('projects',projects),[projects]);useEffect(()=>save('focus-session',focus),[focus])
