  atRiskHabits.forEach(h=>homeEvents.push({id:'habit-'+h.id,kind:'habit',title:'Сегодня можно потерять серию «'+h.title+'»',detail:'Выполни привычку сегодня, чтобы сохранить серию из '+habitStreak(h)+' запланированных дней.',priority:65,habit:h}))
  const importantEvent=homeEvents.sort((a,b)=>b.priority-a.priority)[0]
  const financeStatusLabel=({green:'Прогноз стабильный',yellow:'Небольшой запас',orange:'Есть финансовый риск',red:'Прогнозируемый дефицит',gray:'Недостаточно данных'} as const)[financeHome.status]
  const weekResults=tasks.flatMap(t=>(t.resultHistory??[]).filter(r=>r.at.slice(0,10)>=addDays(today(),-(resultPeriod-1))).map(r=>({task:t.title,value:r.value,unit:t.unit??'',at:r.at,highlight:!!r.highlight}))).sort((a,b)=>b.at.localeCompare(a.at))
