 const habitMonthLabel=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(habitCalendarMonth+'-01T12:00:00'))
 function openTask(t?:Task){setEditingTask(t??null);setTaskDraft(t?{title:t.title,date:t.date,time:t.time==='Без времени'?'':t.time,category:t.category,note:t.note,projectId:t.projectId??'',parentTaskId:t.parentTaskId??'',why:t.why??'',priority:!!t.priority,resultMode:t.resultMode??'none',resultQuestion:t.resultQuestion??'',targetValue:t.targetValue===undefined?'':String(t.targetValue),unit:t.unit??''}:{title:'',date:today(),time:'',category:'Личное',note:'',projectId:'',parentTaskId:'',why:'',priority:false,resultMode:'none',resultQuestion:'',targetValue:'',unit:''});setModal('task')}
 function saveTask(e:FormEvent){e.preventDefault();if(!taskDraft.title.trim())return;const item={...taskDraft,title:taskDraft.title.trim(),time:taskDraft.time||'Без времени',targetValue:taskDraft.targetValue===''?undefined:Number(taskDraft.targetValue)};if(editingTask)setTasks(v=>v.map(t=>t.id===editingTask.id?{...t,...item}:t));else setTasks(v=>[{id:id(),...item,createdAt:new Date().toISOString(),done:false,resultHistory:[]} as Task,...v]);setModal(null);notify(editingTask?'Задача обновлена':'Задача добавлена')}
 function toggleTask(t:Task){if(t.resultMode&&t.resultMode!=='none'){if(t.done)return;setActiveResultTask(t);setResultDraft({value:'',note:'',highlight:false});setModal('result');return}setTasks(v=>v.map(x=>x.id===t.id?{...x,done:!x.done,outcome:x.done?undefined:x.outcome}:x))}
 function recordResult(e:FormEvent){e.preventDefault();if(!activeResultTask||!resultDraft.value.trim())return;const history=[...(activeResultTask.resultHistory??[]),{id:id(),value:resultDraft.value.trim(),note:resultDraft.note.trim(),at:new Date().toISOString(),highlight:resultDraft.highlight}];const numeric=Number(resultDraft.value);const numericMode=activeResultTask.resultMode==='number'||activeResultTask.resultMode==='money';const target=activeResultTask.targetValue;const totalNumber=numericMode?history.reduce((sum,r)=>sum+(Number(r.value)||0),0):numeric;const choicePartial=activeResultTask.resultMode==='choice'&&resultDraft.value==='Частично';const choiceFailed=activeResultTask.resultMode==='choice'&&resultDraft.value==='Не получилось';const hasNumericTarget=numericMode&&target!==undefined&&Number.isFinite(target)&&target>0;const status=choicePartial?'partial':choiceFailed?'not_reached':numericMode?(hasNumericTarget?(totalNumber<target?'partial':totalNumber>target?'exceeded':'reached'):'reached'):'reached';const total=numericMode?String(totalNumber):resultDraft.value.trim();const reached=status==='reached'||status==='exceeded';const notReached=status==='not_reached';const closed=reached||notReached;const stamp=new Date().toISOString();const updatedTask:Task={...activeResultTask,resultHistory:history,resultValue:total,resultStatus:status,lastResultAt:stamp,done:closed,outcome:reached?'reached':notReached?'not_reached':undefined};const shouldPrompt=reached&&activeResultTask.resultMode==='money'&&!activeResultTask.incomePromptDismissed&&!hasTaskIncome(activeResultTask.id)&&Number(total)>0;setTasks(v=>v.map(t=>t.id===activeResultTask.id?updatedTask:t));setMoneyPromptTask(shouldPrompt?updatedTask:null);setModal(shouldPrompt?'money':null);setActiveResultTask(null);notify(reached?'Результат достигнут. Отличная работа!':notReached?'Попытка зафиксирована. Результат не достигнут.':'Промежуточный результат сохранён')}
 function confirmTaskIncome(){if(!moneyPromptTask)return;const added=addIncomeFromTask(moneyPromptTask.id,moneyPromptTask.title,moneyPromptTask.resultValue??'');if(added)setTasks(v=>v.map(t=>t.id===moneyPromptTask.id?{...t,incomeOperationCreated:true}:t));setMoneyPromptTask(null);setModal(null);notify(added?'Доход добавлен в финансы и связан с задачей':'Операция уже существует или сумма некорректна')}
 function declineTaskIncome(){if(moneyPromptTask)setTasks(v=>v.map(t=>t.id===moneyPromptTask.id?{...t,incomePromptDismissed:true}:t));setMoneyPromptTask(null);setModal(null);notify('Результат сохранён без финансовой операции')}
