 function convertThought(t:Thought){const task:Task={id:id(),title:t.text,date:today(),time:'Без времени',category:'Личное',note:'Создано из мысли',createdAt:new Date().toISOString(),why:'Создано из сохранённой мысли',done:false,resultMode:'none',resultHistory:[]};setTasks(v=>[task,...v]);setThoughts(v=>v.map(x=>x.id===t.id?{...x,archived:true,convertedAt:new Date().toISOString(),taskId:task.id}:x));setPage('tasks');setTaskTab('tasks');notify('Создана задача. Исходная мысль перемещена в архив')}
