 function addHabit(e:FormEvent){e.preventDefault();if(!habitDraft.title.trim())return;let days=habitDraft.days;if(habitDraft.schedule==='daily')days=[0,1,2,3,4,5,6];if(habitDraft.schedule==='weekdays')days=[0,1,2,3,4];days=[...new Set(days)].sort((a,b)=>a-b);if(habitDraft.schedule==='custom'&&!days.length){notify('Выбери хотя бы один день');return}const schedule:HabitSchedule={type:habitDraft.schedule,days,target:days.length};const detail=habitDraft.schedule==='daily'?'Каждый день':habitDraft.schedule==='weekdays'?'По будням':days.map(d=>weekdays[d]).join(', ');if(editingHabit){setHabits(v=>v.map(h=>h.id===editingHabit.id?{...h,title:habitDraft.title.trim(),detail,schedule,scheduleHistory:[...(h.scheduleHistory??[{from:h.createdAt??today(),schedule:scheduleAt(h,today())}]).filter(x=>x.from<=today()),{from:addDays(today(),1),schedule}]}:h));notify('Привычка обновлена')}else{setHabits(v=>[{id:id(),title:habitDraft.title.trim(),detail,log:[],createdAt:today(),schedule,scheduleHistory:[{from:today(),schedule}]},...v]);notify('Привычка создана')}setEditingHabit(null);setHabitDraft({title:'',schedule:'daily',days:[],target:0});setModal(null)}
